-- Long-lived tracking token for guest orders.
--
-- Unlike orders.confirmation_token (which is generated by admin-adjust-order
-- and nulled by confirm-customer-order once the customer has paid), this
-- token is set at guest order creation and never nulled. It lets a guest
-- re-open /guest-track/:orderId?token=... at any point in the order lifecycle
-- to see status, items, and delivery/pickup details.
--
-- The token is cryptographically random (generateConfirmationToken in
-- _shared/order-helpers.ts) so leaking orderId alone is insufficient to
-- view order details.

ALTER TABLE public.orders
  ADD COLUMN IF NOT EXISTS guest_tracking_token TEXT;

CREATE INDEX IF NOT EXISTS idx_orders_guest_tracking_token
  ON public.orders (guest_tracking_token)
  WHERE guest_tracking_token IS NOT NULL;

COMMENT ON COLUMN public.orders.guest_tracking_token IS
  'Long-lived token for guest order tracking. Set at creation for guest orders, NULL for authenticated orders. Never nulled post-payment.';
